SELECT r.id, r.task_id AS taskId, r.pull_task_type AS pullTaskType, r.record_id AS recordId, r.card_number AS cardNumber, r.card_status AS cardStatus, r.channel_code AS channelCode, r.channel_name AS channelName, r.open_type AS openType, r.person_code AS personCode, r.person_id AS personId, r.person_name AS personName, r.department_id AS departmentId, r.department_name AS departmentName, r.audience_type AS audienceType, DATE_FORMAT(r.swing_time, '%Y-%m-%d %H:%i:%s') AS swingTime, DATE_FORMAT(r.create_time, '%Y-%m-%d %H:%i:%s') AS createTime, r.open_result AS openResult, r.enter_or_exit AS enterOrExit, r.mapping_user_id AS mappingUserId, r.mapping_card_no AS mappingCardNo, r.mapping_hit AS mappingHit, r.freeze_exempt_flag AS freezeExemptFlag, r.raw_json AS rawJson, DATE_FORMAT(r.ingested_at, '%Y-%m-%d %H:%i:%s') AS ingestedAt FROM twin_dahua_swing_record r WHERE r.channel_code IN
#{ch}
AND r.mapping_hit = 1 AND r.open_result = 1 AND r.swing_time >= #{startTime} AND r.swing_time <= #{endTime} AND NOT EXISTS ( SELECT 1 FROM twin_dahua_activation_state a WHERE a.last_record_id = r.record_id ) ORDER BY r.swing_time ASC
LIMIT #{limit}

SELECT COUNT(1)
FROM twin_dahua_activation_state
WHERE task_id = #{taskId}
  AND user_id = #{userId}
  AND last_record_id = #{recordId}

SELECT COUNT(1)
FROM twin_dahua_swing_record
WHERE 1 = 1
AND task_id = #{taskId}
AND channel_code = #{channelCode}
AND person_code = #{personCode}
AND person_name LIKE CONCAT('%', #{personName}, '%')
AND open_type = #{openType}
AND swing_time >= #{startTime}
AND swing_time <= #{endTime}
AND (enter_or_exit IS NULL OR enter_or_exit = 0)

SELECT id, task_id AS taskId, pull_task_type AS pullTaskType, record_id AS recordId, card_number AS cardNumber, card_status AS cardStatus, channel_code AS channelCode, channel_name AS channelName, open_type AS openType, person_code AS personCode, person_id AS personId, person_name AS personName, department_id AS departmentId, department_name AS departmentName, audience_type AS audienceType, DATE_FORMAT(swing_time, '%Y-%m-%d %H:%i:%s') AS swingTime, DATE_FORMAT(create_time, '%Y-%m-%d %H:%i:%s') AS createTime, open_result AS openResult, enter_or_exit AS enterOrExit, mapping_user_id AS mappingUserId, mapping_card_no AS mappingCardNo, mapping_hit AS mappingHit, freeze_exempt_flag AS freezeExemptFlag, raw_json AS rawJson, DATE_FORMAT(ingested_at, '%Y-%m-%d %H:%i:%s') AS ingestedAt FROM twin_dahua_swing_record WHERE 1 = 1 AND task_id = #{taskId} AND channel_code = #{channelCode}
AND channel_code IN #{c}
AND person_code = #{personCode} AND person_name LIKE CONCAT('%', #{personName}, '%') AND open_type = #{openType} AND enter_or_exit = #{enterOrExit} AND swing_time >= #{startTime} AND swing_time <= #{endTime} ORDER BY swing_time DESC, id DESC LIMIT #{limit} OFFSET #{offset}

SELECT id, task_id AS taskId, record_id AS recordId, card_number AS cardNumber, card_status AS cardStatus, channel_code AS channelCode, channel_name AS channelName, open_type AS openType, person_code AS personCode, person_id AS personId, person_name AS personName, department_id AS departmentId, department_name AS departmentName, audience_type AS audienceType, DATE_FORMAT(swing_time, '%Y-%m-%d %H:%i:%s') AS swingTime, DATE_FORMAT(create_time, '%Y-%m-%d %H:%i:%s') AS createTime, open_result AS openResult, enter_or_exit AS enterOrExit, mapping_user_id AS mappingUserId, mapping_card_no AS mappingCardNo, mapping_hit AS mappingHit, freeze_exempt_flag AS freezeExemptFlag, raw_json AS rawJson, DATE_FORMAT(ingested_at, '%Y-%m-%d %H:%i:%s') AS ingestedAt FROM twin_dahua_swing_record WHERE channel_code = #{channelCode} AND task_id IN #{tid} AND pull_task_type = #{pullTaskType} AND swing_time >= #{startTime} AND swing_time <= #{endTime} AND swing_time > #{afterSwingTime} AND enter_or_exit = #{enterOrExit}
ORDER BY swing_time ASC, id ASC ORDER BY swing_time DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM twin_dahua_swing_record
WHERE channel_code = #{channelCode}
  AND task_id IN
  #{tid}
AND pull_task_type = #{pullTaskType}
AND swing_time >= #{startTime}
AND swing_time <= #{endTime}
AND swing_time > #{afterSwingTime}
AND enter_or_exit = #{enterOrExit}

