WHERE 1 = 1
AND task_id = #{f.taskId}
AND channel_code = #{f.channelCode}

    AND (channel_name LIKE CONCAT('%', #{f.channelName}, '%')
    OR channel_code LIKE CONCAT('%', #{f.channelName}, '%'))

AND person_code = #{f.personCode}
AND person_name LIKE CONCAT('%', #{f.personName}, '%')
AND card_number LIKE CONCAT('%', #{f.cardNumber}, '%')

    AND (department_name LIKE CONCAT('%', #{f.departmentName}, '%')
    OR department_id LIKE CONCAT('%', #{f.departmentName}, '%'))

AND open_type = #{f.openType}
AND enter_or_exit = #{f.enterOrExit}
AND open_result = #{f.openResult}
AND audience_type = #{f.audienceType}
AND mapping_hit = #{f.mappingHit}
AND mapping_hit = 1
AND (open_result IS NULL OR open_result = 1)
AND swing_time >= #{f.startTime}
AND swing_time <= #{f.endTime}

