DELETE FROM twin_dahua_activation_state
WHERE user_id = #{userId}
  AND state IN ('PENDING_ACTIVATION', 'AUTO_EXIT_SCHEDULED')

DELETE FROM twin_dahua_activation_state
WHERE task_id = #{taskId}
  AND user_id = #{userId}
