SELECT COUNT(1)
FROM twin_dahua_activation_state
WHERE task_id = #{taskId}
  AND user_id = #{userId}
  AND UPPER(state) = 'ACTIVATED'

SELECT COUNT(1)
FROM twin_dahua_activation_state
WHERE task_id = #{taskId}
