  AND UPPER(state) = 'AUTO_EXIT_SCHEDULED'
  AND scheduled_exit_at IS NOT NULL

SELECT COUNT(1)
FROM twin_dahua_activation_state
WHERE task_id = #{taskId}
  AND user_id = #{userId}
  AND channel_code = #{pendingChannel}
  AND UPPER(state) = 'PENDING_ACTIVATION'

SELECT DATE_FORMAT(MAX(activated_at), '%Y-%m-%d %H:%i:%s')
FROM twin_dahua_activation_state
WHERE task_id = #{taskId}
  AND user_id = #{userId}
  AND UPPER(state) = 'ACTIVATED'
